test.beforeAll(async()=>{root=process.env.PHASE5_STATIC_CAPTURE??mkdtempSync(join(tmpdir(),'mw-phase5-final-ui-'));owned=!process.env.PHASE5_STATIC_CAPTURE;if(owned){const transform=(code:string,id:string)=>{if(id.endsWith('/apps/pwa/src/owner-offline.ts'))return code.replace("async list(kind:'snapshot'|'draft'|'pending'){","async list(kind:'snapshot'|'draft'|'pending'){if(kind==='snapshot')await (globalThis as any).__syntheticSnapshotRead?.();");if(id.endsWith('/apps/pwa/src/live-main.tsx'))return code+";import {getAuth as fixtureGetAuth,signInWithCustomToken as fixtureSignIn} from 'firebase/auth';globalThis.__syntheticSdk={fixtureGetAuth,fixtureSignIn};import {ownerOfflineRepository as fixtureRepository} from './owner-offline';globalThis.__syntheticRepo=fixtureRepository;import {projectViewedSnapshot as fixtureProjection} from './viewed-snapshot';globalThis.__syntheticProjection=fixtureProjection;"};const script='import{build}from"vite";await build(Object.assign('+JSON.stringify({mode:'live-dev',build:{outDir:join(root,'public'),emptyOutDir:true}})+',{plugins:[{name:"synthetic-sdk-bridge",enforce:"pre",transform:'+transform.toString()+'}]}));';const result=spawnSync(process.execPath,['--input-type=module','-e',script],{encoding:'utf8',env:{...process.env,VITE_FIREBASE_PROJECT_ID:'clever-oasis-508610-n7',VITE_FIREBASE_AUTH_DOMAIN:'clever-oasis-508610-n7.firebaseapp.com',VITE_FIREBASE_API_KEY:'synthetic-public-key',VITE_FIREBASE_APP_ID:'synthetic-app',VITE_API_ORIGIN:'https://mw-credit-app-read-dev-test.run.app',VITE_COMMAND_API_ORIGIN:'https://mw-credit-app-command-dev-test.run.app',VITE_COMMAND_MODE:'dev-owner-testing'}});expect(result.status,result.stderr).toBe(0)}fixture=await startCanonicalFixture(join(root,'public'))});
test.afterAll(async()=>{await fixture?.close();if(owned)rmSync(root,{recursive:true,force:true})});test.setTimeout(45000);
const v='a'.repeat(64),v2='b'.repeat(64),uid='synthetic-phase5-final-owner',requestId='07eae274-c4e9-44e9-bff4-900c3bf37c9b',receiptId='fe93a8d6-3050-449e-9bba-949da4acf246';
