type S={posts:any[],pendingAtPost:any[],close:any,correction:any,preferences:any,deleted:boolean,receiptReads:string[],manualFail:boolean,record:any};
async function repo(page:Page,kind:string){return page.evaluate(async kind=>(window as any).__syntheticRepo({issuer:'https://securetoken.google.com/clever-oasis-508610-n7',uid:'synthetic-phase5-final-owner'}).list(kind),kind)}
async function seed(page:Page,domain:string,id:string,draft:any){await page.evaluate(async({domain,id,draft})=>{await(window as any).__syntheticRepo({issuer:'https://securetoken.google.com/clever-oasis-508610-n7',uid:'synthetic-phase5-final-owner'}).saveDraft(domain+':'+id,{domain,label:'Synthetic '+domain+' final draft',draft})},{domain,id,draft})}
async function saved(page:Page,label:string){if(page.viewportSize()!.width<=1050)await page.getByRole('button',{name:'Open navigation',exact:true}).click();await page.getByRole('button',{name:'Saved payment drafts',exact:true}).filter({visible:true}).click();await page.getByRole('button',{name:new RegExp('^'+label)}).click()}
async function launch(){console.log('C static stage: launch');
 const context=await chromium.launchPersistentContext('',{headless:true,...(mobile?devices['Pixel 7']:devices['Desktop Chrome']),viewport:{width:320,height:900},args:['--ignore-certificate-errors','--host-resolver-rules=MAP dev-lm.mw-credit.com 127.0.0.1:'+fixture.port,'--no-proxy-server']});console.log('C static stage: context ready');const page=await context.newPage();page.on('pageerror',e=>console.log('C synthetic pageerror: '+e.message));const now=Math.floor(Date.now()/1000),token=[{alg:'none',typ:'JWT'},{sub:uid,user_id:uid,aud:'clever-oasis-508610-n7',iss:'https://securetoken.google.com/clever-oasis-508610-n7',iat:now,exp:now+3600,auth_time:now,email:'synthetic@example.test',email_verified:true,firebase:{sign_in_provider:'custom'}}].map(x=>Buffer.from(JSON.stringify(x)).toString('base64url')).join('.')+'.synthetic';
 const s:S={posts:[],pendingAtPost:[],close:closeA,correction:previewA,preferences:preferenceA,deleted:false,receiptReads:[],manualFail:true,record:null};
 await context.route('**/*',async r=>{const u=new URL(r.request().url());if(u.hostname==='dev-lm.mw-credit.com')return r.continue();if(u.hostname==='identitytoolkit.googleapis.com')return r.fulfill({contentType:'application/json',body:JSON.stringify(u.pathname.includes('signInWithCustomToken')?{idToken:token,refreshToken:'synthetic-refresh',expiresIn:'3600',isNewUser:false}:{users:[{localId:uid,email:'synthetic@example.test',emailVerified:true,providerUserInfo:[]}]})});if(u.hostname==='mw-credit-app-read-dev-test.run.app')return r.fulfill({contentType:'application/json',body:JSON.stringify({ok:true,source:'dev',businessDate:'2026-10-09',horizonEnd:'2027-01-09',reviewRequired:false,items:u.pathname.includes('/loans')||u.pathname.endsWith('/upcoming')?[]:[borrower],item:borrower,borrower,nextCursor:null,asOf:new Date().toISOString()})});
 if(u.hostname==='mw-credit-app-command-dev-test.run.app'){
 let data:any={ok:true,items:[],nextCursor:null};
 if(r.request().method()!=='GET'){s.posts.push({path:u.pathname,body:r.request().postDataJSON()});s.pendingAtPost.push(await repo(page,'pending'));return r.abort('failed')}
 if(u.pathname.endsWith('/close-preview'))data=s.close;
 else if(u.pathname.endsWith('/correction-preview')){if(s.deleted)return r.fulfill({status:404,body:'{}'});data={ok:true,item:s.correction}}
 else if(u.pathname==='/api/preferences')data=s.preferences;
 else if(u.pathname==='/api/cash-overview')data={dashboard:{},accounts:[]};
 else if(u.pathname==='/api/cash-statements')data={summary:{openingBalance:'20',moneyIn:'5',moneyOut:'10',netMovement:'-5',closingBalance:'15',transactionCount:1},items:[{id:'C-ledger',date:'2026-10-09',transactionType:'Payment details',amount:'5',balanceAfter:'15',paymentId:'C-payment',notes:'synthetic ledger note'}],nextCursor:null};
 else if(u.pathname.endsWith('/receipt')){const source=u.searchParams.get('source')??'preferred';s.receiptReads.push(source);if(source!=='agent'&&s.manualFail)return r.fulfill({status:422,body:'{}'});return r.fulfill({contentType:'image/png',body:Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a7ZkAAAAASUVORK5CYII=','base64')})}
 else if(u.pathname.startsWith('/api/payment-records/'))data={ok:true,item:{...s.record,asOf:new Date().toISOString(),businessDate:'2026-10-09'}};
 else if(u.pathname==='/api/borrower-options')data={ok:true,accounts,referrers:[{id:'C-other',label:'Synthetic destination'}]};
 return r.fulfill({contentType:'application/json',body:JSON.stringify(data)})}return r.abort()});
 await context.route('https://mw-credit-app-command-dev-test.run.app/api/dashboard',r=>r.fulfill({contentType:'application/json',body:JSON.stringify({collection:{notPaid:0,partiallyPaid:0,overdue:0,fullyPaid:0},forecast:{},portfolio:{},incomeMtd:{},businessCashHeld:[]})}));await page.goto('https://dev-lm.mw-credit.com');console.log('C static stage: page loaded');await expect.poll(()=>page.evaluate(()=>!!navigator.serviceWorker.controller)).toBe(true);await page.evaluate(async()=>{const sdk=(window as any).__syntheticSdk;await sdk.fixtureSignIn(sdk.fixtureGetAuth(),'synthetic-custom-token')});console.log('C static stage: SDK signed in');await page.getByRole('button',{name:'Borrowers',exact:true}).filter({visible:true}).click();await expect(page.getByRole('button',{name:'Add borrower',exact:true})).toBeVisible();await chooseLanguage(page,'EN');return{context,page,s};
}
test('F12 static Close retains CAS until explicit adoption then fresh review freezes request receipt and money',async()=>{const{context,page,s}=await launch();try{await seed(page,'loan','close:C-loan',closeDraft);await saved(page,'Synthetic loan');await expect(page.locator('output')).toHaveText('฿115');s.close={...closeA,sourceVersion:v2,planHash:v2,amount:'120'};await page.getByRole('button',{name:'Review close',exact:true}).click();await expect(page.getByRole('button',{name:'Use current closing amount',exact:true})).toBeVisible();expect((await repo(page,'draft'))[0].value.draft.preview).toEqual(closeA);expect(s.posts).toHaveLength(0);await page.getByRole('button',{name:'Retry review',exact:true}).click();await expect(page.locator('output')).toHaveText('฿115');await page.getByRole('button',{name:'Use current closing amount',exact:true}).click();await expect.poll(async()=>(await repo(page,'draft'))[0].value.draft.preview.sourceVersion).toBe(v2);expect((await repo(page,'draft'))[0].value.draft).toMatchObject({requestId,account:'C-account',method:'Cash',notes:closeDraft.notes,receipt:receiptId});await expect(page.getByRole('button',{name:'Confirm',exact:true})).toHaveCount(0);await page.getByRole('button',{name:'Review close',exact:true}).click();await page.getByRole('button',{name:'Confirm',exact:true}).click();await expect.poll(()=>s.posts.length).toBe(1);expect(s.posts[0].body).toMatchObject({requestId,receiptId,expectedVersion:v2,inputs:{expectedAmount:'120',expectedPlanHash:v2,notes:closeDraft.notes}});await expect.poll(()=>s.pendingAtPost.length).toBe(1);expect(s.pendingAtPost[0][0].value.command).toEqual(s.posts[0].body);await expect(page.getByRole('button',{name:'Check request',exact:true})).toBeVisible();await expect(page.getByRole('button',{name:'Back to details',exact:true})).toBeDisabled();expect(await repo(page,'draft')).toHaveLength(0)}finally{await context.close()}});
test('F12 static correction preserves head receipt split on stale and deleted source before explicit immutable dispatch',async()=>{const{context,page,s}=await launch();try{await seed(page,'payment','correction:C-payment',correctionDraft);await saved(page,'Synthetic payment');await expect(page.getByRole('textbox',{name:/^Notes(?: \*)?$/})).toHaveValue(fields.notes);s.correction={...previewA,sourceVersion:v2,predecessorRequestId:'changed-head'};await page.getByRole('button',{name:'Review correction',exact:true}).click();await expect(page.getByRole('alert')).toContainText('The source changed');expect((await repo(page,'draft'))[0].value.draft.preview.sourceVersion).toBe(v);expect((await repo(page,'draft'))[0].value.draft.receiptId).toBe(receiptId);s.deleted=true;await page.getByRole('button',{name:'Review correction',exact:true}).click();await expect(page.getByRole('button',{name:'Confirm',exact:true})).toHaveCount(0);expect(s.posts).toHaveLength(0);s.deleted=false;s.correction=previewA;await page.getByRole('button',{name:'Review correction',exact:true}).click();await page.getByRole('button',{name:'Confirm',exact:true}).click();await expect.poll(()=>s.posts.length).toBe(1);expect(s.posts[0].body).toMatchObject({requestId,receiptId,expectedVersion:v,predecessorRequestId:requestId,inputs:{receiptMode:'replace',fields:{notes:fields.notes,allocations:[line]}}});expect(s.pendingAtPost[0][0].value.command).toEqual(s.posts[0].body)}finally{await context.close()}});
test('F12 legacy preference draft seeds readonly cash filters; receipt drilldown never silently falls back',async()=>{const{context,page,s}=await launch();try{await seed(page,'preference','own',{preferences:preferenceA,account:'C-account',date:'2026-10-09',language:'English'});await saved(page,'Synthetic preference');await expect(page.getByRole('button',{name:'Save preferences',exact:true})).toHaveCount(0);await expect(page.getByRole('combobox',{name:/^Account(?: \*)?$/})).toHaveValue('C-account');await expect(page.getByLabel('Statement Date',{exact:true})).toHaveValue('2026-10-09');expect((await repo(page,'draft'))[0].value.draft.preferences.item.version).toBe(v);expect(s.posts).toHaveLength(0);await page.getByRole('combobox',{name:/^Account(?: \*)?$/}).selectOption('');await page.getByRole('combobox',{name:/^Account(?: \*)?$/}).selectOption('C-account');await expect(page.getByRole('button',{name:'Payment details',exact:true})).toBeVisible();s.record={id:'C-payment',version:v,borrowerName:'SYNTHETIC receipt borrower',amountReceived:'10',paymentDate:'2026-10-09',paymentMethod:'Cash',allocationMethod:'Selected Charges',status:'Posted',originalOutcomeStatus:'posted',originalRecordedAt:'2026-10-08T01:00:00Z',receiptReference:'unknown-native',agentReceiptPresent:true,allocations:[],repayments:[],cashMovements:[]};await page.getByRole('button',{name:'Payment details',exact:true}).click();await expect(page.getByRole('region',{name:'Full payment details',exact:true})).toBeVisible();await expect.poll(()=>s.receiptReads).toEqual(['preferred']);await expect(page.locator('main')).toContainText('Receipt unavailable');expect(s.receiptReads).not.toContain('agent');await page.getByRole('button',{name:'Agent receipt',exact:true}).click();await expect(page.getByRole('img',{name:'Verified receipt evidence',exact:true})).toBeVisible();expect(s.receiptReads).toEqual(['preferred','agent']);expect(s.posts).toHaveLength(0);expect(await page.locator('body').evaluate(e=>e.scrollWidth)).toBeLessThanOrEqual(320)}finally{await context.close()}});

