 await page.locator('.borrower-tile-main').first().click();const summary=page.getByRole('region',{name:'Borrower record',exact:true});await expect(summary).toContainText('Synthetic exact note');await expect(page.getByRole('button',{name:'Full borrower details / edit',exact:true})).toHaveCount(0);await expect(page.getByRole('button',{name:'Receive selected charges',exact:true})).toHaveCount(0);await expect(summary.getByRole('button',{name:'New loan',exact:true})).toBeVisible();await expect(summary.getByRole('button',{name:'Edit borrower',exact:true})).toBeVisible();
