// Phase6 final checkpoint: synthetic HTTP, actual Firebase SDK/static worker/IndexedDB.
const managementLabelsC=['Partners','Cash Position','Cash Accounts','Cash Holders','Contributions','Settlements','Cash Movements','Loan Assessments','Analytics'];
async function managementNavC(page:Page,label:string){await page.setViewportSize({width:1440,height:900});const toggle=page.getByRole('button',{name:'Management',exact:true}).filter({visible:true});if(await toggle.getAttribute('aria-expanded')!=='true')await toggle.click();await page.getByRole('button',{name:label,exact:true}).filter({visible:true}).click()}
async function managementRoutesC(context:any){const reads:string[]=[];await context.route('https://mw-credit-app-command-dev-test.run.app/api/management/**',r=>{const u=new URL(r.request().url());reads.push(u.pathname+u.search);const kind=u.pathname.split('/')[3],id=u.pathname.split('/')[4];const common={id:id??'C-management',version:v,label:'SYNTHETIC management',active:true,sortOrder:1,createdAt:'2026-10-09T05:00:00Z'};let data:any={businessDate:'2026-10-09',asOf:Date.now(),items:[common],nextCursor:null};if(id)data={...data,item:common};if(kind==='cash-holders')data={...data,items:[{...common,id:'C-holder',label:'Synthetic holder'}]};if(kind==='partners')data={...data,items:[{...common,id:'C-partner',label:'Synthetic partner',partnerRole:'A'}],...(id?{item:{...common,partnerRole:'A',loginEmail:'synthetic@example.invalid',email:'welct0407@mw-credit.com',igIntegrationEnabled:null,aiReviewer:false,netAvailableToSettle:'10',totalProfitEarned:'20',currentPoolShare:'0.5'}}:{})};if(kind==='cash-accounts')data={...data,items:[{...common,id:'C-account',label:'Synthetic account',holderId:'ch:lisa',holderLabel:'Lisa'}]};if(kind==='analytics-overview')data={metrics:{totalProfit:'12345',netProfit:'10000',outstandingPrincipal:'500',activeLoans:'2'},refreshTarget:{id:'C-statistics',version:v}};if(kind==='analytics-chart')data={metric:u.searchParams.get('metric'),asOf:'2026-10-09T05:00:00.000000Z',businessDate:'2026-10-09',totalValue:'-2.50',count:3,unknownCount:1,negativeCount:1,otherValue:'0',pieItems:[{id:'C-pos',name:'Synthetic positive',value:'1.5'},{id:'C-neg',name:'Synthetic negative',value:'-4'},{id:'C-null',name:'Synthetic unknown',value:null}],items:[{id:'C-pos',name:'Synthetic positive',label:'2026-10-09',value:'1.5',unknownCount:0},{id:'C-neg',name:'Synthetic negative',label:'2026-10-08',value:'-4',unknownCount:0},{id:'C-null',name:'Synthetic unknown',label:'2026-10-07',value:null,unknownCount:1}],nextCursor:null};if(kind==='assessments')data={...data,items:[{...common,id:'C-assessment',assessmentId:'Synthetic assessment',borrowerLabel:'Synthetic borrower',freshness:'out-of-date',recommendation:null,forecastStart:'2026-10-08',forecastEnd:'2026-10-08'}],...(id?{item:{...common,assessmentId:'Synthetic assessment',borrowerId:'C-borrower',borrowerLabel:'Synthetic borrower',proposedLoanAmount:'100.25',minimumDailyProfitRate:'0.01',forecastStart:'2026-10-08',forecastEnd:'2026-10-08',freshness:'out-of-date',recommendation:null,asOfDate:'2026-10-08',calculatedAt:'2026-10-08T05:00:00Z'}}:{})};if(kind==='cash-position')data={dashboard:{totalCashPool:'100',availableCash:'80'},accounts:[{id:'C-account',label:'Synthetic account',holderId:'C-holder',holderLabel:'Synthetic holder',currentBalance:'100',initialized:false}],holders:[{id:'C-holder',label:'Synthetic holder',cashIn:'100',cashOut:'0',currentBalance:'100',businessCashHeld:'100',reimbursementDue:'0'}]};if(kind==='openings')data={item:{id:'C-holder',version:v,sourceVersion:v,reviewedBasisHash:v,holderBalance:'0',accounts:[{accountId:'C-account',label:'Synthetic account',initialized:false,balance:'0'}]}};return r.fulfill({contentType:'application/json',body:JSON.stringify(data)})});return reads}

test('P6 T9 ordered management forms preserve flags and strict320 bilingual geometry without creating commands',async({},info)=>{const{context,page,s}=await launch();try{await managementRoutesC(context);const expected:any={'Cash Holders':['Holder Name','Active','Sort Order'],'Cash Accounts':['Cash Holder','Account Label','Bank Name','Account Number','Default Account','Active','Sort Order','Alternative Account Number'],Partners:['Partner Name','Partner Role','Email','Instagram Username','Language Preference','IG Integration Enabled','Login Email','AI Reviewer']};for(const section of ['Cash Holders','Cash Accounts','Partners']){await managementNavC(page,section);await page.getByRole('button',{name:'New record',exact:true}).click();const form=page.locator('main form');expect(await form.locator(':scope > label > .field-title').allTextContents()).toEqual(expected[section]);if(section==='Partners'){await expect(page.getByRole('checkbox',{name:'IG Integration Enabled',exact:true})).toBeDisabled();await expect(page.getByRole('checkbox',{name:'AI Reviewer',exact:true})).toBeDisabled()}await page.setViewportSize({width:320,height:900});for(const language of ['EN','ไทย']as const){await chooseLanguage(page,language);expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(320);expect(await form.locator('input,select').evaluateAll(es=>es.filter(e=>{const r=e.getBoundingClientRect();return r.width>1&&(r.left<0||r.right>320)}).length)).toBe(0)}await chooseLanguage(page,'EN');await page.getByRole('button',{name:'Back to details',exact:true}).click()}expect(s.posts).toHaveLength(0);expect(await repo(page,'pending')).toHaveLength(0)}finally{await context.close()}});
test('P6 T9 management unsent draft reload preserves exact inputs then pending-before-POST recovery remains immutable',async()=>{const{context,page,s}=await launch();try{await managementRoutesC(context);await managementNavC(page,'Partners');await page.getByRole('button',{name:'New record',exact:true}).click();await page.getByRole('textbox',{name:/^Partner\ Name(?: \*)?$/}).fill('Synthetic partner draft ไทย');await page.getByRole('combobox',{name:/^Partner\ Role(?: \*)?$/}).selectOption('B');await page.getByRole('textbox',{name:/^Login\ Email(?: \*)?$/}).fill('synthetic@example.invalid');await expect.poll(async()=>(await repo(page,'draft')).filter((r:any)=>r.value.domain==='management').length).toBe(1);const draft=(await repo(page,'draft'))[0];await page.reload();await expect(page.getByRole('button',{name:'Borrowers',exact:true}).filter({visible:true})).toBeVisible();await saved(page,'Synthetic partner draft');await expect(page.getByRole('textbox',{name:/^Partner\ Name(?: \*)?$/})).toHaveValue('Synthetic partner draft ไทย');expect((await repo(page,'draft'))[0].value.draft.inputs).toEqual(draft.value.draft.inputs);expect(s.posts).toHaveLength(0);await page.getByRole('button',{name:'Review change',exact:true}).click();await page.getByRole('button',{name:'Confirm',exact:true}).click();await expect(page.getByRole('button',{name:'Check request',exact:true})).toBeVisible();expect(s.posts).toHaveLength(1);const command=s.posts[0].body;expect(command).toMatchObject({operation:'partner.create',targetId:draft.value.draft.id,inputs:draft.value.draft.inputs});await expect.poll(()=>s.pendingAtPost.length).toBe(1);expect(s.pendingAtPost[0][0].value).toMatchObject({domain:'management',command});expect(await repo(page,'draft')).toHaveLength(0);await expect(page.getByRole('button',{name:'Back to details',exact:true})).toBeDisabled();await page.reload();expect(s.posts).toHaveLength(1);await expect.poll(async()=>(await repo(page,'pending')).length).toBe(1);const statusReads:string[]=[];await context.route('https://mw-credit-app-command-dev-test.run.app/api/operations/*',r=>{statusReads.push(new URL(r.request().url()).pathname);return r.fulfill({contentType:'application/json',body:JSON.stringify({kind:'unresolved',safeToUseNewRequestId:false})})});await saved(page,'New record');await page.getByRole('button',{name:'Check request',exact:true}).click();await expect.poll(()=>statusReads.length).toBe(1);expect(statusReads[0]).toBe('/api/operations/'+command.requestId);expect(s.posts).toHaveLength(1);expect((await repo(page,'pending'))[0].value.command).toEqual(command)}finally{await context.close()}});
test('P6 T9 financial form source order and payment-state choices remain distinct from explicit confirmation',async()=>{const{context,page,s}=await launch();try{await managementRoutesC(context);const expected:any={Contributions:['Partner','Contribution Date','Transaction Type','Amount','Notes'],Settlements:['Settlement Date','Partner','Amount','Status','Transfer Date','Notes','Cash Account'],'Cash Movements':['Movement Date','Movement Type','Amount','From Account','To Account','Notes']};for(const section of ['Contributions','Settlements','Cash Movements']){await managementNavC(page,section);await page.getByRole('button',{name:'New record',exact:true}).click();const form=page.locator('main form');expect(await form.locator(':scope > label > .field-title').allTextContents()).toEqual(expected[section]);if(section==='Settlements')expect(await page.getByRole('combobox',{name:/^Status(?: \*)?$/}).locator('option').allTextContents()).toEqual(['Pending','Completed']);if(section==='Cash Movements'){await page.getByRole('combobox',{name:/^Movement\ Type(?: \*)?$/}).selectOption('Expense Reimbursement');await expect(page.locator('form label').filter({hasText:'Related Expense'})).toBeVisible()}expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(1440);await page.getByRole('button',{name:'Back to details',exact:true}).click()}expect(s.posts).toHaveLength(0)}finally{await context.close()}});
