test('P6 T8 analytics nine charts preserve signed unavailable values and Full only dispatches after explicit Confirm',async()=>{const{context,page,s}=await launch();try{const reads=await managementRoutesC(context);await managementNavC(page,'Analytics');await expect(page.locator('.management-chart-grid .management-chart')).toHaveCount(9);await expect.poll(()=>reads.filter(p=>p.startsWith('/api/management/analytics-chart')).length).toBe(9);await expect(page.locator('.management-pie')).toHaveCount(0);await expect(page.locator('.management-chart-grid')).toContainText('A complete positive total is required');await expect(page.locator('.management-chart-grid')).toContainText('Synthetic unknown');expect(s.posts).toHaveLength(0);await page.getByRole('button',{name:'Recalculate full history',exact:true}).click();await expect(page.getByRole('button',{name:'Confirm',exact:true})).toBeVisible();await expect(page.locator('main')).toContainText('Rebuild the complete supported history.');expect(s.posts).toHaveLength(0);await page.getByRole('button',{name:'Confirm',exact:true}).click();await expect.poll(()=>s.posts.length).toBe(1);expect(s.posts[0].body).toMatchObject({operation:'analytics.refresh',targetId:'C-statistics',expectedVersion:v,inputs:{mode:'Full'}});await expect.poll(()=>s.pendingAtPost.length).toBe(1);expect(s.pendingAtPost[0][0].value.command).toEqual(s.posts[0].body);await expect(page.getByRole('button',{name:'Check request',exact:true})).toBeVisible()}finally{await context.close()}});
